import { defineConfig } from 'vite';
import vue from '@vitejs/plugin-vue';
export default defineConfig({ root: 'src/vue', plugins: [vue()], build: { outDir: '../../dist-vite', emptyOutDir: true } });

import { createApp } from 'vue';
import App from './App.vue';
createApp(App).mount('#app');

import assert from 'node:assert/strict';
import { readFile, readdir, rm, stat } from 'node:fs/promises';
import test from 'node:test';
import { build } from 'vite';

const output = new URL('../dist-vite/', import.meta.url);
const viteTemp = new URL('../node_modules/.vite-temp/', import.meta.url);

test('Vite bundles the complete Vue application', { timeout: 120000 }, async () => {
  try {
    await build({ configFile: new URL('../vite.config.mjs', import.meta.url).pathname, configLoader: 'native', logLevel: 'silent' });
    assert.equal((await stat(new URL('index.html', output))).isFile(), true);
    const assets = await readdir(new URL('assets/', output));
    const javascript = assets.filter((name) => name.endsWith('.js'));
    assert.ok(javascript.length > 0);
    const bundle = (await Promise.all(javascript.map((name) => readFile(new URL(`assets/${name}`, output), 'utf8')))).join('');
    assert.match(bundle, /Standing Desk/);
    assert.match(bundle, /Desk Lamp/);
    assert.doesNotMatch(bundle, /TODO storefront/);
  } finally {
    await Promise.all([
      rm(output, { recursive: true, force: true }),
      rm(viteTemp, { recursive: true, force: true })
    ]);
  }
});
